function save(notify=false){if(online){if(notify)toast('החדר נשמר אוטומטית בשרת. חזרו מאותו מכשיר עם קישור החדר.');return;}try{localStorage.setItem(KEY,JSON.stringify(s));if(notify)toast('העיר נשמרה בדפדפן הזה.');}catch{if(saveAvailable){saveAvailable=false;toast('השמירה המקומית חסומה בדפדפן; אל תסגרו את הדף כדי לשמור על ההתקדמות.');}}}
function beep(freq=480){if(!sound)return;try{const A=window.AudioContext||window.webkitAudioContext,ac=new A(),o=ac.createOscillator(),g=ac.createGain();o.connect(g);g.connect(ac.destination);o.frequency.value=freq;g.gain.setValueAtTime(.035,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.15);o.start();o.stop(ac.currentTime+.16);setTimeout(()=>ac.close(),230);}catch{}}
const canAct=()=>!lobby&&!networkBusy&&s.active===me&&s.phase==='action'&&!s.players[me].out&&!s.quiz;
function enabled(cost=0,ap=1,condition=true){return canAct()&&s.players[me].cash>=cost&&s.players[me].ap>=ap&&condition&&!s.players[me].adventure.challenge;}
function button(text,cmd,arg=null,cost=0,ap=1,condition=true,style='secondary'){return `<button class="${style}" data-cmd="${cmd}" data-arg="${esc(JSON.stringify(arg))}" ${enabled(cost,ap,condition)?'':'disabled'}>${text}<span>${cost?fmt(cost)+' ◒':''}${ap?' · '+ap+' צעדים':''}</span></button>`;}
async function perform(cmd,arg=null){if(networkBusy)return;const epoch=sessionEpoch;try{if(cmd==='permit'&&arg?.mode==='shady'&&!confirm('בחירה בדיונית בסיכון: 1,000 קרדיטים, 65% להיתר מיידי, מוניטין 7− וחשיפה 30+. כישלון גורר קנס נוסף של 650. להמשיך?'))return;const before=s.logs[0];if(online){networkBusy=true;if(await sendRoom(cmd,arg)===false)return;}else action(s,me,cmd,arg);beep(cmd==='answer'?s.quizResult?.correct?650:230:440);if(cmd==='extendSeason'&&s.phase!=='finished')shownWinner=false;save();render();if(cmd==='quiz'||cmd==='answer'){renderQuiz();if(!$('quiz-modal').open)$('quiz-modal').showModal();}else if(cmd==='auction')$('auction-modal').showModal();else if(s.logs[0]!==before)toast(s.logs[0].text);}catch(e){toast(e.message);}finally{if(epoch===sessionEpoch)networkBusy=false;render();if(s.quiz?.player===me)renderQuiz();}}
