function renderLandList(){const aa=s.assets.filter(a=>filter===null||a.district===filter);$('land-count').textContent=`${aa.filter(a=>a.owner===null).length} מגרשים פנויים`;const list=$('land-list'),scroll=list.scrollLeft;list.innerHTML=aa.map(a=>`<button data-asset="${a.id}" class="land-card ${a.id===selected?'selected':''}"><small>${esc(a.city)} · ${BUILDINGS[a.type]?.name??'מגרש'}</small><b>${esc(a.street)}</b><span>${a.owner===null?fmt(a.price)+' קרדיטים':a.owner===me?'בבעלותך'+(a.permit==='pending'?' · היתר בטיפול':''):esc(s.players[a.owner].name)}</span></button>`).join('');list.scrollLeft=scroll;}
function render(){updateNetworkStatus();$('wellness').textContent=s.players[me].wellness;$('wellness-note').textContent=s.players[me].vacationUntil>=s.round?'בונוס חופשה 10% עד רבעון '+s.players[me].vacationUntil:'נסיעות וחופשות משפרות רווחה';const p=s.players[me],f=forecast(s,me),owned=s.assets.filter(a=>a.owner===me),active=s.players[s.active],finished=s.phase==='finished';$('quarter').textContent=String(s.maxRounds?Math.min(s.round,s.maxRounds):s.round).padStart(2,'0');$('cash').textContent=fmt(p.cash);$('cash-note').textContent=p.loan?`חוב פתוח: ${fmt(p.loan)} קרדיטים`:'קרדיטים במשחק';$('income').textContent=(f.net>=0?'+':'')+fmt(f.net);$('income').style.color=f.net>=0?'':'#f3b18b';$('income-note').textContent=f.shortage?'מחסור באנרגיה מפחית הכנסה ב־35%':'תזרים עירוני · הבורסה מחושבת בנפרד';$('worth').textContent=fmt(worth(s,me));$('assets-count').textContent=`${owned.length} מגרשים · ${owned.filter(a=>a.level).length} מבנים`;$('reputation').textContent=p.rep;$('risk-note').textContent=`חשיפה לביקורת: ${p.heat}%`;$('energy').textContent=`${f.demand} / ${f.supply}`;$('energy').style.color=f.shortage?'#f3b18b':'#edf0e7';$('energy-note').textContent=f.shortage?'הוסיפו סולארי או מחקר טכנולוגיה':'צריכה / קיבולת';$('player-name').textContent=p.name;$('rank').textContent=`${['יזם מתחיל','מפתח עירוני','בונה שכונות','אדריכל אימפריות'][Math.min(3,level(p)-1)]} · רמה ${level(p)}`;$('xp').textContent=`${p.xp%120} / 120 XP`;$('xp-bar').style.width=(p.xp%120)/1.2+'%';$('avatar').textContent=['♟','♜','♝','♛'][p.avatar-1];$('avatar-rank').textContent=['I','II','III','IV'][p.avatar-1];$('prestige').textContent=fmt(score(s,me))+(s.goal?' / '+fmt(s.goal):' · עונה פתוחה');$('prestige-bar').style.width=(s.goal?Math.min(100,score(s,me)/s.goal*100):0)+'%';$('pending-count').textContent=owned.filter(a=>a.permit==='pending').length;
 $('rivals').innerHTML=s.players.filter(p=>p.id!==me).map(p=>`<div class="rival ${s.active===p.id?'active':''} ${p.out?'out':''}" style="--c:${p.color}"><i>♜</i><div><b>${esc(p.name)}</b><small>${p.out?'יצא מהתחרות':`${s.assets.filter(a=>a.owner===p.id).length} מגרשים · רמה ${level(p)}`}</small></div><strong>${fmt(score(s,p.id))}</strong></div>`).join('');$('event-name').textContent=EVENTS[s.event].name;$('event-desc').textContent=EVENTS[s.event].desc;$('turn-title').textContent=finished?`${s.players[s.winner]?.name??'העיר'} ניצח בעונה!`:s.phase==='auction'?'מכרז פתוח. מי יזכה בנכס?':p.out?'האימפריה שלך יצאה מהתחרות.':s.active===me?'התור שלך. העיר מחכה.':`התור של ${active.name}`;$('turn-note').textContent=finished?'לחצו לפתיחת עיר חדשה':s.phase==='auction'?'הפעולות מושהות עד לסיום המכרז':s.active===me?`${p.ap} צעדי פעולה זמינים · ${p.quizTurn===s.turn?'אתגר הידע נוצל':'טריוויה זמינה לבונוס'}`:'המתחרים בוחרים מגרשים ומקדמים תכניות';$('turn-avatar').textContent=active.bot?'♜':'♟';$('turn-avatar').style.color=active.color;$('ap-dots').innerHTML=Array.from({length:Math.max(6,p.ap)},(_,i)=>`<i class="${i<p.ap?'on':''}"></i>`).join('');$('end-turn').disabled=lobby||networkBusy||!finished&&(s.active!==me||s.phase!=='action'||!!s.quiz);$('end-turn').innerHTML=finished?'עיר חדשה <span>↗</span>':'סיום התור <span>←</span>';$('trivia').disabled=lobby||networkBusy||finished||s.active!==me||s.phase!=='action'||p.out||!!p.adventure.challenge||p.quizTurn===s.turn&&!s.quiz;$('turn-number').textContent=`מהלך ${s.turn}${online&&!lobby?' · לתור עד '+new Date(online.deadline).toLocaleTimeString('he-IL',{hour:'2-digit',minute:'2-digit'}):''}`;
 const icons={exchange:'↗',adventure:'⌁',season:'∞',conflict:'⚔',syndicate:'◉',security:'⬡',repair:'✚',system:'✦',event:'◉',permit:'▧',buy:'⌂',build:'↑',green:'♧',district:'▦',research:'✧',trivia:'?',mine:'◈',auction:'↗',risk:'!',finance:'◒',mission:'⚑',win:'♛'};$('journal').innerHTML=s.logs.slice(0,4).map(l=>`<div class="log-row"><i>${icons[l.type]??'·'}</i><span>${esc(l.text)}</span><small>Q${l.quarter}</small></div>`).join('');renderInspector();renderLandList();if($('property-modal').open)renderPropertyDetails();renderWarStatus();renderRouteDock();if(tab!=='city')renderTab();updateAuction();if(finished&&!shownWinner){shownWinner=true;toast(`${s.players[s.winner]?.name??'העונה'} ניצח עם ${fmt(s.winner!==null?score(s,s.winner):0)} יוקרה.`);}}
